// TASK-0034 — Find & Open, product acceptance in real WebView2. No simulated
// DOM, no alternate renderer, no personal data: the tree under test was
// generated by task0034-seed-proof.py and dies with the proof root.
//
// Reuses TASK-0033's harness technique (REAL_ROOT registered directly into a
// fresh sandbox catalogue, then the real product driven through CDP) rather
// than building a second framework.
import assert from "node:assert/strict";
import { writeFile, readFile } from "node:fs/promises";
import { setTimeout as pause } from "node:timers/promises";
import { join } from "node:path";

const port = Number(process.argv[2]);
const variant = process.argv[3];
assert(/^task0034-[a-f0-9]+$/.test(variant));

const seed = JSON.parse(
  (
    await new Promise((resolve, reject) => {
      let text = "";
      process.stdin.setEncoding("utf8");
      process.stdin.on("data", (c) => (text += c));
      process.stdin.on("end", () => resolve(text));
      process.stdin.on("error", reject);
    })
  ).replace(/^﻿/, ""), // PowerShell's pipe prepends a UTF-8 BOM.
);
const { brainId, absolutePath, needleName, needleRelativePath } = seed;

let target;
for (let n = 0; n < 100; n++) {
  try {
    const pages = await (await fetch(`http://127.0.0.1:${port}/json/list`)).json();
    target = pages.find((p) => p.type === "page");
    if (target) break;
  } catch {}
  await pause(200);
}
assert(target, "WebView2 CDP page unavailable");
const ws = new WebSocket(target.webSocketDebuggerUrl);
await new Promise((resolve, reject) => {
  ws.addEventListener("open", resolve, { once: true });
  ws.addEventListener("error", reject, { once: true });
});
let serial = 0;
const pending = new Map();
const fatal = [];
ws.addEventListener("message", ({ data }) => {
  const event = JSON.parse(data);
  if (event.id) {
    const p = pending.get(event.id);
    pending.delete(event.id);
    if (event.error) p?.reject(new Error(JSON.stringify(event.error)));
    else p?.resolve(event.result);
  } else if (
    event.method === "Runtime.exceptionThrown" ||
    (event.method === "Log.entryAdded" && event.params.entry.level === "error")
  ) {
    fatal.push(event);
  }
});
const send = (method, params = {}) =>
  new Promise((resolve, reject) => {
    const id = ++serial;
    pending.set(id, { resolve, reject });
    ws.send(JSON.stringify({ id, method, params }));
  });
async function evaluate(expression) {
  const r = await send("Runtime.evaluate", { expression, awaitPromise: true, returnByValue: true });
  if (r.exceptionDetails) throw new Error(r.exceptionDetails.exception?.description ?? r.exceptionDetails.text);
  return r.result.value;
}
async function until(expression, limit = 240000) {
  const start = Date.now();
  while (Date.now() - start < limit) {
    if (await evaluate(expression)) return;
    await pause(100);
  }
  throw new Error(`timeout: ${expression}`);
}
const invoke = (command, args = {}) =>
  evaluate(`window.__TAURI_INTERNALS__.invoke(${JSON.stringify(command)},${JSON.stringify(args)})`);
await send("Runtime.enable");
await send("Log.enable");
await send("Page.enable");

async function key(k) {
  const vk = k === "Enter" ? 13 : 0;
  await send("Input.dispatchKeyEvent", {
    type: "keyDown",
    key: k,
    code: k,
    windowsVirtualKeyCode: vk,
    nativeVirtualKeyCode: vk,
    ...(k === "Enter" ? { text: "\r", unmodifiedText: "\r" } : {}),
  });
  await send("Input.dispatchKeyEvent", { type: "keyUp", key: k, code: k, windowsVirtualKeyCode: vk, nativeVirtualKeyCode: vk });
  await pause(120);
}
async function activate(selector) {
  const found = await evaluate(`!!document.querySelector(${JSON.stringify(selector)})`);
  assert(found, `activate: selector not found — ${selector}`);
  await evaluate(`document.querySelector(${JSON.stringify(selector)}).focus()`);
  await key("Enter");
}
async function clickButtonWithText(text) {
  const found = await evaluate(
    `(()=>{const b=[...document.querySelectorAll('button')].find(x=>x.textContent.trim()===${JSON.stringify(text)});if(!b) return false; b.focus(); return true;})()`,
  );
  assert(found, `button not found: ${text}`);
  await key("Enter");
}
/** Real text insertion through the browser's own input pipeline — not a
 * synthetic `.value =` assignment, so React's controlled `<input>` sees a
 * genuine `input` event exactly as it would from a person typing. */
async function typeInto(selector, text) {
  await evaluate(`document.querySelector(${JSON.stringify(selector)}).focus()`);
  await send("Input.insertText", { text });
  await pause(150);
}
const jargon = ["view_budget_or_focus", "outside_current_projection", "omitted_direct_children", "enfants directs hors vue"];
function assertNoJargon(text, where) {
  for (const word of jargon) assert(!text.includes(word), `internal jargon "${word}" leaked into ${where}`);
}
const escaped = absolutePath.split("\\").join("\\\\");
function assertNoPathLeak(text, where) {
  assert(!text.includes(absolutePath) && !text.includes(escaped), `absolute path leaked into ${where}`);
}

const results = {};

// --- 1. index the large synthetic REAL_ROOT tree, by a real keystroke -------
await until(`document.querySelector('[data-testid="lifecycle-open"]') && !document.querySelector('[data-testid="lifecycle-open"]').disabled`);
await activate('[data-testid="lifecycle-refresh"]');
await until(`!document.querySelector('[data-testid="lifecycle-open"]').disabled && document.querySelectorAll('[role="treeitem"]').length > 0`);
// Read-only from here: `map_view`/`map_search_nodes` never advance the
// revision, unlike `map_refresh`/`map_rebuild` — calling either of the
// latter again here, only to read a report, would advance the backend's
// revision a second time behind the app's own React state, which learns
// about a new revision solely through its own UI-triggered lifecycle
// actions. That exact mismatch is what step 6 deliberately produces later,
// on purpose, through the UI itself.
const build = await invoke("map_view", { brainId });
assert(build.nodeCount >= 5000, `indexed corpus too small: ${build.nodeCount}`);
results.indexedNodeCount = build.nodeCount;

// --- 2. confirm the needle is genuinely outside the ordinary projection -----
const root = await invoke("map_view", { brainId });
assert(
  !root.nodes.some((n) => n.relativePath === needleRelativePath),
  "the needle must not already sit in the ordinary root projection",
);
results.needleOutsideOrdinaryProjection = true;

// --- 3. search for it, by real typing --------------------------------------
await until(`!!document.getElementById("map-search-input")`);
await typeInto("#map-search-input", needleName);
await until(`document.querySelector('[data-testid="search-total"]')?.getAttribute('data-total') === "1"`, 20000);

const domTotal = await evaluate(`document.querySelector('[data-testid="search-total"]').getAttribute('data-total')`);
assert.equal(domTotal, "1", "the DOM must show exactly one hit");
const hitText = await evaluate(`document.querySelector('[data-testid="search-hit"]')?.textContent ?? ''`);
assert(hitText.includes(needleName), `search hit must show the file name: ${hitText}`);
assert(hitText.includes(needleRelativePath), `search hit must show the relative path: ${hitText}`);

// Cross-check against a direct call to the same command the UI itself calls.
const searchPage = await invoke("map_search_nodes", { brainId, query: needleName, offset: 0, limit: 50 });
assert.equal(searchPage.total, 1);
assert.equal(searchPage.items.length, 1);
assert.equal(searchPage.items[0].relativePath, needleRelativePath);
assert.equal(searchPage.items[0].brainId, brainId);
const domRevision = await evaluate(`document.querySelector('[data-testid="search-total"]').getAttribute('data-index-revision')`);
assert.equal(Number(domRevision), searchPage.indexRevision, "the DOM must report the same revision the DTO carries");
results.search = {
  total: searchPage.total,
  indexRevision: searchPage.indexRevision,
  boundedToProductLimit: searchPage.limit <= 50,
};

// --- 4. an empty query must not dump the corpus -----------------------------
// The dedicated "Effacer" affordance, activated by a real keystroke — also
// the product's own answer to "effacement simple".
await activate('[data-testid="search-clear"]');
await pause(150);
const clearedValue = await evaluate(`document.getElementById("map-search-input").value`);
assert.equal(clearedValue, "", "Effacer must empty the search field");
const emptyResults = await evaluate(`!!document.querySelector('[data-testid="search-results"]')`);
assert.equal(emptyResults, false, "an empty query must show no results panel at all");

// --- 5. activate the result: new projection, correct selection -------------
await typeInto("#map-search-input", needleName);
await until(`document.querySelector('[data-testid="search-total"]')?.getAttribute('data-total') === "1"`, 20000);
await activate('[data-testid="search-hit"]');
await until(`document.querySelector('.details__name')?.textContent?.trim() === ${JSON.stringify(needleName)}`);
const focusedPath = await evaluate(`document.querySelector('.details__path')?.textContent?.trim()`);
assert.equal(focusedPath, needleRelativePath, "the details panel must show the activated node");
const activeDescendant = await evaluate(`document.querySelector('[data-testid="composed-canvas"]')?.getAttribute('aria-activedescendant')`);
assert(activeDescendant?.endsWith(`-map-node-${searchPage.items[0].nodeId}`), "the selected card must be the search hit");
results.activationLoadedNewProjectionAndSelected = true;

// --- 6. refresh advances the revision; the UI reflects it, not a stale one --
const revisionBeforeRefresh = searchPage.indexRevision;
await activate('[data-testid="lifecycle-refresh"]');
await until(
  `Number(document.querySelector('[data-testid="search-total"]')?.getAttribute('data-index-revision') ?? -1) > ${revisionBeforeRefresh}`,
  30000,
);
const revisionAfterRefresh = Number(
  await evaluate(`document.querySelector('[data-testid="search-total"]').getAttribute('data-index-revision')`),
);
assert(revisionAfterRefresh > revisionBeforeRefresh, "a refresh must advance the revision the search UI reports");
// The same query, at the new revision, must still resolve correctly rather
// than silently keep serving the page read at the old one.
const rebuiltPage = await invoke("map_search_nodes", { brainId, query: needleName, offset: 0, limit: 50 });
assert.equal(rebuiltPage.total, 1);
assert.equal(rebuiltPage.indexRevision, revisionAfterRefresh);
results.revisionInvalidation = {
  before: revisionBeforeRefresh,
  after: revisionAfterRefresh,
  uiAutoReloadedRatherThanStayingStale: true,
};

// --- 7. Ouvrir dans l'Explorateur, on a synthetic target only ---------------
// A single direct invoke — the same command the DetailsPanel button calls —
// is the deterministic proof host; the button's own wiring (it forwards
// exactly `{ reference }` and nothing else) is proven by
// `DetailsPanel.test.tsx`, so this replay does not also click it and spawn a
// second Explorer window for the same fact.
const revealReference = { brainId, nodeId: searchPage.items[0].nodeId };
await invoke("map_reveal_node", { reference: revealReference });
results.revealSpawnSucceeded = true;

// --- 8. no absolute path or internal jargon anywhere visible ---------------
const bodyText = await evaluate("document.body.textContent");
assertNoJargon(bodyText, "page body text");
assertNoPathLeak(bodyText, "page body text");
for (const payload of [root, searchPage, rebuiltPage]) {
  const text = JSON.stringify(payload);
  assertNoPathLeak(text, "invoke payload");
}
const hostLog = await readFile(join(".filetopo-sandbox", variant, "app.log"), "utf8").catch(() => "");
assertNoPathLeak(hostLog, "host log");
assertNoJargon(hostLog, "host log");

assert.equal(fatal.length, 0, "fatal page/console errors");

const screenshot = await send("Page.captureScreenshot", { format: "png" });
await writeFile(`.filetopo-sandbox/${variant}/find-open.png`, Buffer.from(screenshot.data, "base64"));

const host = await invoke("map_host_info");
const artifact = {
  task: "TASK-0034",
  status: "NONCANONICAL_ENGINEERING_EVIDENCE",
  engine: "Windows Tauri / real WebView2",
  webviewVersion: host.webviewVersion,
  tauriVersion: host.tauriVersion,
  sqliteVersion: host.sqliteVersion,
  source: "REAL_ROOT registered internally (task0034-seed-proof.py) -> map_search_nodes -> map_view -> MapApp/DetailsPanel -> map_reveal_node",
  tree: {
    generatedByTheProofNotByTheUser: true,
    personalDataUsed: false,
    indexedNodeCount: build.nodeCount,
    needleRelativePath,
  },
  ...results,
  fatalConsoleErrors: fatal.length,
  absolutePathLeak: false,
  internalJargonLeak: false,
  historicalCommandsReregistered: false,
  limits: [
    "No personal brain: the analysed tree was generated by task0034-seed-proof.py and dies with the proof root",
    "map_reveal_node was invoked directly rather than also through a UI click, to avoid spawning a second visible Explorer window for the same fact; the button's own wiring is proven by DetailsPanel.test.tsx",
    "Development workstation; not a modest-laptop acceptance test",
    "A real explorer.exe window may remain open after this run — TASK-0034 explicitly forbids killing it globally, so it is left for Windows to manage",
  ],
};
await writeFile("docs/performance/runs/TASK-0034-webview2.json", JSON.stringify(artifact, null, 2) + "\n");
console.log(JSON.stringify(artifact));
ws.close();
